class Solution {
    public int[] mergeShelves(int[] left, int[] right) {
        int[] out = Arrays.copyOf(left, left.length + right.length);
        System.arraycopy(right, 0, out, left.length, right.length);
        Arrays.sort(out);
        return out;
    }
}

