static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int* mergeShelves(int* left, int leftSize, int* right, int rightSize, int* returnSize) {
    int n = leftSize + rightSize;
    int* out = malloc(n * sizeof(int));
    memcpy(out, left, leftSize * sizeof(int));
    memcpy(out + leftSize, right, rightSize * sizeof(int));
    qsort(out, n, sizeof(int), cmp_int);
    *returnSize = n;
    return out;
}

code.python:
class Solution:
    def mergeShelves(self, left: List[int], right: List[int]) -> List[int]:
        out, i, j = [], 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                out.append(left[i]); i += 1
            else:
                out.append(right[j]); j += 1
        out.extend(left[i:])
        out.extend(right[j:])
        return out

