        while (i < left.size() && j < right.size()) out.push_back(left[i] <= right[j] ? left[i++] : right[j++]);
        while (i < left.size()) out.push_back(left[i++]);
        while (j < right.size()) out.push_back(right[j++]);
        return out;
    }
};

